BHJ_st.name='BHJ'; 
BHJ_st.lat=23.25;
BHJ_st.lon=69.67;
BHJ_st.alt=0000;
BHJ_st.env='Con';
BHJ_st.footp='U';
%%
% data imported via the import tool from matlab

BHJ_rd_h.Properties.DimensionNames{1}='Time';
BHJ_rd_h.Properties.VariableNames{2}='Ba1_A';
BHJ_rd_h.Properties.VariableNames{3}='Ba2_A';
BHJ_rd_h.Properties.VariableNames{4}='Ba3_A';
BHJ_rd_h.Properties.VariableNames{5}='Ba4_A';
BHJ_rd_h.Properties.VariableNames{6}='Ba5_A';
BHJ_rd_h.Properties.VariableNames{7}='Ba6_A';
BHJ_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(BHJ_rd_h);
%%
% make abs
sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19]; %for the 7 wavelengths with an exponent of -1
BHJ_rd_h.Ba1_A=BHJ_rd_h.Ba1_A .*sigma(1);
BHJ_rd_h.Ba2_A=BHJ_rd_h.Ba2_A .*sigma(2);
BHJ_rd_h.Ba3_A=BHJ_rd_h.Ba3_A .*sigma(3);
BHJ_rd_h.Ba4_A=BHJ_rd_h.Ba4_A .*sigma(4);
BHJ_rd_h.Ba5_A=BHJ_rd_h.Ba5_A .*sigma(5);
BHJ_rd_h.Ba6_A=BHJ_rd_h.Ba6_A .*sigma(6);
BHJ_rd_h.Ba7_A=BHJ_rd_h.Ba7_A .*sigma(7);


%%
BHJ_rd=retime(BHJ_rd_h,'daily',@nanmedian);
%%
datevec(BHJ_rd.Time(1)) % begin in 2016,  %[output:64594d52]
datevec(BHJ_rd.Time(end)) % end in 2025 (with some months of 2026) %[output:1a187574]
plotFigControl(BHJ_rd,BHJ_st.name);  %[output:5410f5e0] %[output:295ac24c] %[output:2aac389b] %[output:7ab0b935] %[output:22ba0219] %[output:575558db] %[output:990dadab] %[output:3ecf0f31]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
BHJ_cal=compute_exp_D(BHJ_rd,names_abs,lambdaAE7); %[output:9b665e8d] %[output:20447355] %[output:28572d81] %[output:26cc96d7] %[output:366e738c] %[output:3596f705] %[output:0dbb55f1]
plotFigControl_cal(BHJ_cal,BHJ_st.name); %[output:824d9dbf] %[output:0ab0a995] %[output:83925028]
%%
%HOMOGENEITY

break_BHJ_abs_BP=change_point_analysis_Def(BHJ_rd,names_abs,0.05,'BHJ','Absorption'); %[output:142d53ad] %[output:566e2925] %[output:985241e0] %[output:538557d7] %[output:95f9c400] %[output:16ba036a]
T_BHJ_abs_BP=make_table_breakpoints_def(break_BHJ_abs_BP); %[output:5134adf9] %[output:97996231] %[output:182653dd] %[output:94694f9e] %[output:2efb1488] %[output:1981da76] %[output:66d3da93] %[output:5ce568fa] %[output:4206ce49] %[output:0c7e902c]

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:173a0df3]
break_BHJ_expA_BP=change_point_analysis_Def(BHJ_cal,names_expA,0.05,'BHJ','Absorption exponent'); %[output:0601c916] %[output:33ea1d46] %[output:677222c6] %[output:2968e8a7]
T_BHJ_expA_BP=make_table_breakpoints_def(break_BHJ_expA_BP); %[output:6f5a869e] %[output:58b26da8]
%%
BHJ_tr=outerjoin(BHJ_rd, BHJ_cal);
BHJ_tr.y=year(BHJ_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2016-01-01','2024-01-01');
BHJ_tr=BHJ_tr(P,:);

% % names=fieldnames(BHJ_tr);
% % c=startsWith(names,["U"]) | endsWith(names,["_dry","_A","_br","_gr"]) | contains(names,["00","3","tsi"]);
% % N=names(c);
% % for i=1:length(N)
% %     BHJ_tr.(N{i})=[];
% % end

%
BHJ_tr.Ba1_A=[];
BHJ_tr.Ba2_A=[];
BHJ_tr.Ba4_A=[];
BHJ_tr.Ba5_A=[];
BHJ_tr.Ba6_A=[];
BHJ_tr.Ba7_A=[];

BHJ_tr.BB=[];

BHJ_tr.expA_bgAE=[];
BHJ_tr.expA_brAE=[];
BHJ_tr.expA_grAE=[];
%%
% % % data in Mm-1
% % BHJ_tr.Ba3_A=BHJ_tr.Ba3_A.*1e6;
%%
[BHJ_result_MK,BHJ_result_LMSlog,BHJ_result_LMSlin]=all_trend_STN(BHJ_tr,BHJ_st); %[output:57a23896] %[output:55c485ab] %[output:10f8625d] %[output:6b638428] %[output:26992fe5] %[output:6a23d59e] %[output:7fe92e24] %[output:6506620f]

writetable(BHJ_result_MK,'BHJ_res_MK.txt'); %, 'delimiter',',' )
writetable(BHJ_result_LMSlog,'BHJ_res_LMSlog.txt'); 
writetable(BHJ_result_LMSlin,'BHJ_res_LMSlin.txt'); 
%plot_10y_in_two(BHJ_result_MK, BHJ_st,'y');
%%
 timetable_to_netcdf(BHJ_tr,'BHJ_tr_def.nc');

